import React, { useState, useRef } from "react";
import "./App.css";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");
  const [mode, setMode] = useState("fast");

  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [trials, setTrials] = useState([]);
  const [loading, setLoading] = useState(false);

  const summaryRef = useRef(null);

  // 🚀 FAST SEARCH HANDLER
  const handleSearch = async () => {
    if (!disease.trim()) {
      alert("Enter disease");
      return;
    }

    setLoading(true);

    // ⚡ FAST MODE → NO BACKEND CALL
    if (mode === "fast") {
      setSummary(`Quick overview of ${disease}:

• Common condition affecting body systems  
• Requires early diagnosis  
• Treatment depends on severity  
• Consult medical professional for accuracy`);

      setPublications([]);
      setTrials([]);

      setLoading(false);
      return;
    }

    // 🔬 DEEP MODE → BACKEND CALL (with timeout)
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 8000); // 8 sec max

      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent,
          location,
        }),
        signal: controller.signal,
      });

      clearTimeout(timeout);

      const data = await res.json();

      setSummary(data.insights || "No insights");
      setPublications(data.publications || []);
      setTrials(data.clinical_trials || []);

      // scroll
      setTimeout(() => {
        summaryRef.current?.scrollIntoView({ behavior: "smooth" });
      }, 200);

    } catch (err) {
      console.error(err);
      setSummary("⚠️ Server slow or not responding. Try Fast Mode.");
    }

    setLoading(false);
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSearch();
  };

  return (
    <div className="app">

      {/* LEFT */}
      <div className="sidebar">
        <h2>🧠 AI Medical</h2>

        <input
          placeholder="Disease..."
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
        />

        <div className="mode-toggle">
          <button
            className={mode === "fast" ? "active" : ""}
            onClick={() => setMode("fast")}
          >
            ⚡ Fast
          </button>

          <button
            className={mode === "deep" ? "active" : ""}
            onClick={() => setMode("deep")}
          >
            🔬 Deep
          </button>
        </div>
      </div>

      {/* CENTER */}
      <div className="main">
        <textarea
          placeholder="Ask your question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
          onKeyDown={handleKeyPress}
        />

        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
        />

        <button onClick={handleSearch}>
          {loading ? "⏳ Loading..." : "Search"}
        </button>

        {summary && (
          <div className="summary" ref={summaryRef}>
            <h3>Summary</h3>
            {summary.split("\n").map((line, i) => (
              <p key={i}>{line}</p>
            ))}
          </div>
        )}
      </div>

      {/* RIGHT */}
      <div className="right">
        <div className="card">
          <h3>📄 Papers</h3>
          {publications.length === 0
            ? <p>No data</p>
            : publications.map((p, i) => (
                <p key={i}>{p.title}</p>
              ))}
        </div>

        <div className="card">
          <h3>🧪 Trials</h3>
          {trials.length === 0
            ? <p>No data</p>
            : trials.map((t, i) => (
                <p key={i}>{t.title}</p>
              ))}
        </div>
      </div>

    </div>
  );
}

export default App;
